import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/features/expenses/data/expense_repository.dart';import 'package:pos_app/shared/presentation/database_list_screen.dart';class ExpensesScreen extends StatelessWidget{const ExpensesScreen({super.key});@override Widget build(BuildContext context)=>DatabaseListScreen(title:'Gastos',query:'SELECT id,expense_date,concept,amount_cents,payment_method FROM expenses ORDER BY id DESC',action:(c)async{final v=await textForm(c,'Nuevo gasto',['Concepto','Monto centavos']);if(v!=null)await ExpenseRepository(appDatabase).create(concept:v[0],amountCents:int.parse(v[1]));});}
